#!/usr/bin/env python3
import pathlib
import subprocess
import textwrap
import unittest

ROOT = pathlib.Path(__file__).resolve().parents[1]


class Core(unittest.TestCase):
    def run_node(self, source: str) -> subprocess.CompletedProcess[str]:
        completed = subprocess.run(
            ['node', '-e', textwrap.dedent(source), str(ROOT)],
            capture_output=True,
            text=True,
        )
        self.assertEqual(completed.returncode, 0, completed.stderr)
        return completed

    def test_semantic_and_adversarial_matrix(self):
        completed = self.run_node(r'''const assert=require('assert');const C=require(process.argv[1]+'/src/core/atlas_clock.js');const E=require(process.argv[1]+'/src/core/atlas_events.js');const S=require(process.argv[1]+'/src/ports/atlas_storage.js');let checks=0;const ok=(condition,message)=>{assert.ok(condition,message);checks+=1;};const throws=(fn,pattern)=>{assert.throws(fn,pattern);checks+=1;};const equal=(left,right)=>{assert.deepStrictEqual(left,right);checks+=1;};throws(()=>C.assertCanonicalTimestamp('2026-01-01T00:00:00+00:00'),/NON_CANONICAL/);const clock=new C.ControlledAtlasClock('2026-01-01T00:00:00.000Z');throws(()=>E.canonical({required:'ok',forbiddenUndefined:undefined}),/NON_CANONICAL_VALUE/);const keyCollision={};keyCollision['é']=1;keyCollision['e\u0301']=2;throws(()=>E.canonical(keyCollision),/DUPLICATE_NORMALIZED_KEY/);const courseRef={packageLineageId:'p',courseLineageId:'c'};const objectiveRef={courseRef,objectiveId:'o'};const activityRef=id=>({courseRef,activityLineageId:id});const contentRevisionRef={packageLineageId:'p',packageRevisionId:'r',packageDigest:'sha256:'+'a'.repeat(64)};const claimId='atlas-claim-sha256:'+'b'.repeat(64);function makePlan(items,durationMinutes=5){const total=items.reduce((sum,item)=>sum+item.estimatedMinutes,0);const payload={schemaVersion:'atlas.session-plan.v1',engineVersion:'v',courseRef,contentRevisionRef,durationMinutes,items,totalEstimatedMinutes:total,unusedMinutes:durationMinutes-total,};const hex=E.hash('learnit.atlas.m1.v0.3/plan-digest',payload);return{planId:'atlas-plan-sha256:'+hex,planDigest:'sha256:'+hex,payload};}const activities=new Map([['practice',{type:'qcm',answer:'A',scoringRuleId:'qcm.practice.v1',score:raw=>raw==='A'}],['correction',{type:'qcm',answer:'C',scoringRuleId:'qcm.correction.v1',score:raw=>raw==='C'}],['validation',{type:'qcm',answer:'V',scoringRuleId:'qcm.validation.v1',score:raw=>raw==='V'}],['maintenance',{type:'qcm',answer:'M',scoringRuleId:'qcm.maintenance.v1',score:raw=>raw==='M'}],]);const acceptedRegistry={activity:ref=>activities.get(ref.activityLineageId),validateClaim:(item,context)=>item.independenceClaimId===claimId&&context.independenceClaimId===claimId&&E.sameCanonical(context.objectiveRef,objectiveRef)&&!E.sameCanonical(context.sourceActivityRef,context.targetActivityRef)&&E.sameCanonical(context.contentRevisionRef,contentRevisionRef),};const noClaimAuthorityRegistry={activity:acceptedRegistry.activity};const rejectedRegistry={activity:acceptedRegistry.activity,validateClaim:()=>false};const practicePlan=makePlan([{position:0,objectiveRef,activityRef:activityRef('practice'),action:'start-practice',executionClass:'practice',estimatedMinutes:2,}]);E.validatePlan(practicePlan);checks+=1;throws(()=>E.validatePlan({...practicePlan,extra:true}),/UNKNOWN_FIELD/);const storage=new S.InMemoryAtlasStorage();const core=new S.AtlasCoreService({storage,clock,registry:acceptedRegistry});const request=core.prepareStartRequest(practicePlan.planDigest);const session=core.startSession(request.startRequestId,practicePlan);equal(session,core.startSession(request.startRequestId,practicePlan));ok(storage.learningEvents.filter(event=>event.kind==='session-started').length===1);const wrong=core.commitActivitySubmission(session.sessionId,0,'B');ok(wrong.execution.outcome==='incorrect');ok(!Object.prototype.hasOwnProperty.call(wrong.execution,'validationAdmissible'));ok(core.evidence()[0].state==='review-needed');const right=core.commitActivitySubmission(session.sessionId,0,'A');ok(right.execution.outcome==='correct');core.requestAssistance(session.sessionId,0,'hint');ok(core.evidence()[0].practiceAttempts===2);const expectedEventId=E.eventId({eventVersion:right.event.eventVersion,kind:right.event.kind,executionId:right.event.executionId,});ok(right.event.eventId===expectedEventId);ok(right.event.eventId!==E.eventId(E.without(right.event,'eventId')));const sameIdentityDifferentTimestamp={...right.event,occurredAt:'2026-01-02T00:00:00.000Z'};E.validatePedagogicalEvent(sameIdentityDifferentTimestamp);checks+=1;const correctionPlan=makePlan([{position:0,objectiveRef,activityRef:activityRef('correction'),action:'correct-practice',executionClass:'correction',estimatedMinutes:2,correctsEventId:wrong.event.eventId,}]);const correctionRequest=core.prepareStartRequest(correctionPlan.planDigest);const correctionSession=core.startSession(correctionRequest.startRequestId,correctionPlan);const correction=core.commitActivitySubmission(correctionSession.sessionId,0,'C');ok(correction.event.kind==='activity-corrected');ok(core.evidence()[0].correctionsCompleted===1);const validationPlan=makePlan([{position:0,objectiveRef,activityRef:activityRef('validation'),action:'attempt-validation',executionClass:'validation',estimatedMinutes:2,validationBasisEventId:right.event.eventId,independenceClaimId:claimId,}]);const validationRequest=core.prepareStartRequest(validationPlan.planDigest);const validationSession=core.startSession(validationRequest.startRequestId,validationPlan);const validation=core.commitActivitySubmission(validationSession.sessionId,0,'V');ok(validation.execution.executionClass==='validation');ok(core.evidence()[0].state==='validated-recently');const failClosedStorage=new S.InMemoryAtlasStorage();const failClosedCore=new S.AtlasCoreService({storage:failClosedStorage,clock,registry:noClaimAuthorityRegistry});const pReq=failClosedCore.prepareStartRequest(practicePlan.planDigest);const pSession=failClosedCore.startSession(pReq.startRequestId,practicePlan);const pEvent=failClosedCore.commitActivitySubmission(pSession.sessionId,0,'A').event;const failClosedValidationPlan=makePlan([{position:0,objectiveRef,activityRef:activityRef('validation'),action:'attempt-validation',executionClass:'validation',estimatedMinutes:2,validationBasisEventId:pEvent.eventId,independenceClaimId:claimId,}]);const vReq=failClosedCore.prepareStartRequest(failClosedValidationPlan.planDigest);const vSession=failClosedCore.startSession(vReq.startRequestId,failClosedValidationPlan);const beforeFailClosed=JSON.stringify(failClosedStorage.snapshot());throws(()=>failClosedCore.commitActivitySubmission(vSession.sessionId,0,'V'),/VALIDATION_CLAIM_AUTHORITY_REQUIRED/);ok(JSON.stringify(failClosedStorage.snapshot())===beforeFailClosed);const exported=core.exportState();ok(exported.namespace==='learnit.atlas.m1.v2');equal(exported.contentRevisionDigests,[contentRevisionRef.packageDigest]);throws(()=>core.importState({atlasStateVersion:'0.2',namespace:'learnit.atlas.m1.v1'}),/UNSUPPORTED/);const importedStorage=new S.InMemoryAtlasStorage();const importedCore=new S.AtlasCoreService({storage:importedStorage,clock,registry:acceptedRegistry});ok(importedCore.importState(exported)===true);ok(importedCore.evidence()[0].state==='validated-recently');const noAuthorityImportCore=new S.AtlasCoreService({storage:new S.InMemoryAtlasStorage(),clock,registry:noClaimAuthorityRegistry,});throws(()=>noAuthorityImportCore.importState(exported),/VALIDATION_CLAIM_AUTHORITY_REQUIRED/);const rejectedImportCore=new S.AtlasCoreService({storage:new S.InMemoryAtlasStorage(),clock,registry:rejectedRegistry,});throws(()=>rejectedImportCore.importState(exported),/VALIDATION_CLAIM_NOT_ACCEPTED/);const objectiveMismatch=structuredClone(exported);const changedObjective={courseRef,objectiveId:'foreign'};const validationEvent=objectiveMismatch.learningEvents.find(event=>event.executionId===validation.execution.executionId);validationEvent.objectiveRef=changedObjective;throws(()=>importedCore.importState(objectiveMismatch),/EVENT_EXECUTION_RELATION_INVALID|EVENT_EXECUTION_OBJECTIVE_MISMATCH/);const executionPlanMismatch=structuredClone(exported);const importedExecution=executionPlanMismatch.scoredExecutions.find(entry=>entry.executionId===right.execution.executionId);importedExecution.itemPosition=99;importedExecution.executionId=E.executionId(E.without(importedExecution,'executionId'));const importedEvent=executionPlanMismatch.learningEvents.find(event=>event.executionId===right.execution.executionId);importedEvent.executionId=importedExecution.executionId;importedEvent.eventId=E.eventId(E.pedagogicalEventIdentity(importedEvent));throws(()=>importedCore.importState(executionPlanMismatch),/EXECUTION_PLAN_RELATION_INVALID/);const badCorrection=structuredClone(exported);const correctionEvent=badCorrection.learningEvents.find(event=>event.eventId===correction.event.eventId);correctionEvent.correctsEventId=right.event.eventId;correctionEvent.eventId=E.eventId(E.pedagogicalEventIdentity(correctionEvent));const correctionExecution=badCorrection.scoredExecutions.find(entry=>entry.executionId===correction.execution.executionId);const correctionSessionMeta=badCorrection.atlasMeta.sessions[correctionExecution.sessionRef.sessionId];correctionSessionMeta.plan.payload.items[0].correctsEventId=right.event.eventId;const newHex=E.hash('learnit.atlas.m1.v0.3/plan-digest',correctionSessionMeta.plan.payload);correctionSessionMeta.plan.planDigest='sha256:'+newHex;correctionSessionMeta.plan.planId='atlas-plan-sha256:'+newHex;throws(()=>importedCore.importState(badCorrection),/PLAN_ID_DIGEST_MISMATCH|INVALID_CORRECTION_TARGET|EXECUTION_PLAN_RELATION_INVALID|INVALID_ATLAS_META/);storage.injectFailure();const counts=[storage.scoredExecutions.length,storage.learningEvents.length,storage.resumeStates[0].itemStates[0].submissionOrdinal];throws(()=>core.commitActivitySubmission(session.sessionId,0,'A'),/FAULT_INJECTED/);equal([storage.scoredExecutions.length,storage.learningEvents.length,storage.resumeStates[0].itemStates[0].submissionOrdinal],counts);const beforeLifecycle=JSON.stringify(core.evidence());core.lifecycle(session.sessionId,'session-interrupted');core.lifecycle(session.sessionId,'session-resumed');ok(JSON.stringify(core.evidence())===beforeLifecycle);console.log(`ATLAS_CORE_SEMANTIC_PASS ${checks}/${checks}`);''')
        print(completed.stdout.strip())
        self.assertIn('ATLAS_CORE_SEMANTIC_PASS', completed.stdout)

    def test_indexeddb_atomic_reopen_matrix(self):
        completed = self.run_node(r'''const assert=require('assert');const C=require(process.argv[1]+'/src/core/atlas_clock.js');const E=require(process.argv[1]+'/src/core/atlas_events.js');const I=require(process.argv[1]+'/src/adapters/atlas_indexeddb.js');function nested(value,path){return path.split('.').reduce((current,part)=>current&&current[part],value);}function successfulRequest(result){const request={result,error:null,onsuccess:null,onerror:null};queueMicrotask(()=>{if(request.onsuccess)request.onsuccess();});return request;}function createTransactionalFakeIndexedDb(){const databases=new Map();function connection(record){return{objectStoreNames:{contains:name=>record.keyPaths.has(name)},createObjectStore(name,options){record.keyPaths.set(name,options.keyPath);record.stores.set(name,new Map());return{};},transaction(names,mode){const selected=Array.isArray(names)?names:[names];const working=new Map(selected.map(name=>[name,new Map([...record.stores.get(name).entries()].map(([key,value])=>[key,structuredClone(value)])),]));let aborted=false;const transaction={error:null,oncomplete:null,onabort:null,onerror:null,objectStore(name){if(!working.has(name))throw new Error('STORE_NOT_IN_TRANSACTION');return{clear(){working.get(name).clear();return successfulRequest(undefined);},put(value){const key=nested(value,record.keyPaths.get(name));if(key===undefined)throw new Error('MISSING_KEY');working.get(name).set(key,structuredClone(value));return successfulRequest(key);},getAll(){return successfulRequest([...working.get(name).values()].map(value=>structuredClone(value)));},get(key){return successfulRequest(working.get(name).has(key)?structuredClone(working.get(name).get(key)):undefined);},};},abort(){if(aborted)return;aborted=true;transaction.error=Object.assign(new Error('AbortError'),{name:'AbortError'});queueMicrotask(()=>{if(transaction.onabort)transaction.onabort();});},};setTimeout(()=>{if(aborted)return;if(mode==='readwrite'){for(const name of selected)record.stores.set(name,working.get(name));}if(transaction.oncomplete)transaction.oncomplete();},0);return transaction;},close(){},};}return{open(name,version){const request={result:null,error:null,onupgradeneeded:null,onsuccess:null,onerror:null};queueMicrotask(()=>{let record=databases.get(name);const upgrade=!record||version>record.version;if(!record){record={version,keyPaths:new Map(),stores:new Map()};databases.set(name,record);}else record.version=Math.max(record.version,version);request.result=connection(record);if(upgrade&&request.onupgradeneeded)request.onupgradeneeded();if(request.onsuccess)request.onsuccess();});return request;},};}(async()=>{let checks=0;const fake=createTransactionalFakeIndexedDb();const clock=new C.ControlledAtlasClock('2026-01-01T00:00:00.000Z');const courseRef={packageLineageId:'p',courseLineageId:'c'};const objectiveRef={courseRef,objectiveId:'o'};const contentRevisionRef={packageLineageId:'p',packageRevisionId:'r',packageDigest:'sha256:'+'a'.repeat(64)};const activityRef={courseRef,activityLineageId:'practice'};const activity={type:'qcm',answer:'A',scoringRuleId:'qcm.v1',score:raw=>raw==='A'};const registry={activity:ref=>ref.activityLineageId==='practice'?activity:null};const payload={schemaVersion:'atlas.session-plan.v1',engineVersion:'v',courseRef,contentRevisionRef,durationMinutes:5,items:[{position:0,objectiveRef,activityRef,action:'start-practice',executionClass:'practice',estimatedMinutes:2}],totalEstimatedMinutes:2,unusedMinutes:3,};const hex=E.hash('learnit.atlas.m1.v0.3/plan-digest',payload);const plan={planId:'atlas-plan-sha256:'+hex,planDigest:'sha256:'+hex,payload};const storage=await I.IndexedDbAtlasStorage.open(fake);const core=new I.IndexedDbAtlasCoreService({storage,clock,registry});const request=await core.prepareStartRequest(plan.planDigest);const session=await core.startSession(request.startRequestId,plan);await core.commitActivitySubmission(session.sessionId,0,'B');assert.deepStrictEqual(I.STORE_KEY_PATHS,{learningEvents:'eventId',scoredExecutions:'executionId',resumeStates:'sessionRef.sessionId',atlasMeta:'key'});checks+=1;const committedCounts=[storage.learningEvents.length,storage.scoredExecutions.length,storage.resumeStates.length];storage.close();const reopened=await I.IndexedDbAtlasStorage.open(fake);assert.deepStrictEqual([reopened.learningEvents.length,reopened.scoredExecutions.length,reopened.resumeStates.length],committedCounts,);checks+=1;const reopenedCore=new I.IndexedDbAtlasCoreService({storage:reopened,clock,registry});const beforeAbort=reopened.snapshot();reopened.injectAbortAfterStore('scoredExecutions');await assert.rejects(reopenedCore.commitActivitySubmission(session.sessionId,0,'A'),/AbortError|INDEXEDDB_TRANSACTION_ABORTED/,);checks+=1;assert.deepStrictEqual(reopened.snapshot(),beforeAbort);checks+=1;reopened.close();const afterAbort=await I.IndexedDbAtlasStorage.open(fake);assert.deepStrictEqual(afterAbort.snapshot(),beforeAbort);checks+=1;const exported=reopenedCore.exportState();const secondFake=createTransactionalFakeIndexedDb();const importStorage=await I.IndexedDbAtlasStorage.open(secondFake);const importCore=new I.IndexedDbAtlasCoreService({storage:importStorage,clock,registry});importStorage.injectAbortAfterStore('learningEvents');await assert.rejects(importCore.importState(exported),/AbortError|INDEXEDDB_TRANSACTION_ABORTED/);checks+=1;importStorage.close();const emptyAfterAbort=await I.IndexedDbAtlasStorage.open(secondFake);assert.deepStrictEqual([emptyAfterAbort.learningEvents.length,emptyAfterAbort.scoredExecutions.length,emptyAfterAbort.resumeStates.length],[0,0,0],);checks+=1;const successfulImport=new I.IndexedDbAtlasCoreService({storage:emptyAfterAbort,clock,registry});assert.strictEqual(await successfulImport.importState(exported),true);checks+=1;emptyAfterAbort.close();const importedReopen=await I.IndexedDbAtlasStorage.open(secondFake);assert.deepStrictEqual([importedReopen.learningEvents.length,importedReopen.scoredExecutions.length,importedReopen.resumeStates.length],[exported.learningEvents.length,exported.scoredExecutions.length,exported.resumeStates.length],);checks+=1;console.log(`ATLAS_CORE_INDEXEDDB_PASS ${checks}/${checks}`);})().catch(error=>{console.error(error);process.exit(1);});''')
        print(completed.stdout.strip())
        self.assertIn('ATLAS_CORE_INDEXEDDB_PASS', completed.stdout)

    def test_forbidden_dependencies(self):
        text = '\n'.join(path.read_text() for path in ROOT.rglob('atlas_*.js'))
        for forbidden in ('fetch(', 'WebSocket', 'XMLHttpRequest', 'Math.random', 'learnit_atlas_m1_v1'):
            self.assertNotIn(forbidden, text)


if __name__ == '__main__':
    unittest.main(verbosity=2)
